/*!
 * Bootstrap v5.3.0 (https://getbootstrap.com/)
 * Minimal JS for Modal functionality
 * For production, download full bootstrap.bundle.min.js from:
 * https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js
 */

(function() {
  'use strict';
  
  // Simple Modal implementation
  window.BootstrapModal = class {
    constructor(element) {
      this.element = element;
      this.backdrop = null;
      
      // Setup close button click handlers
      const closeButtons = this.element.querySelectorAll('[data-bs-dismiss="modal"]');
      closeButtons.forEach(btn => {
        btn.addEventListener('click', () => this.hide());
      });
    }
    
    show() {
      this.element.classList.add('show');
      this.element.style.display = 'block';
      this.element.setAttribute('aria-modal', 'true');
      this.element.setAttribute('role', 'dialog');
      this.element.removeAttribute('aria-hidden');
      document.body.classList.add('modal-open');
      
      // Create backdrop
      this.backdrop = document.createElement('div');
      this.backdrop.className = 'modal-backdrop fade show';
      document.body.appendChild(this.backdrop);
      
      // Click outside to close
      this.backdrop.addEventListener('click', () => this.hide());
    }
    
    hide() {
      this.element.classList.remove('show');
      this.element.style.display = 'none';
      this.element.setAttribute('aria-hidden', 'true');
      this.element.removeAttribute('aria-modal');
      this.element.removeAttribute('role');
      document.body.classList.remove('modal-open');
      
      if (this.backdrop) {
        this.backdrop.remove();
        this.backdrop = null;
      }
    }
    
    toggle() {
      if (this.element.classList.contains('show')) {
        this.hide();
      } else {
        this.show();
      }
    }
  };
  
  // ESC key to close modal
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const modals = document.querySelectorAll('.modal.show');
      modals.forEach(modal => {
        if (modal._bsModal) {
          modal._bsModal.hide();
        }
      });
    }
  });
})();

